package com.kuaixietech.integrationsdk.paymentprotocol;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.integration.IntegrationHttp;
import com.kuaixietech.integrationsdk.social.SocialServiceContext;
import java.net.http.HttpRequest;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class AlipayExplicitModeTest {
 final IntegrationHttp http=mock(IntegrationHttp.class);final ObjectMapper json=new ObjectMapper();final KeyPair pair=keys();
 static KeyPair keys(){try{var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);return g.generateKeyPair();}catch(Exception e){throw new AssertionError(e);}}
 SocialServiceContext context(String mode){return new SocialServiceContext("ALIPAY","alipay",mode,Map.of("app_id","2026000000000001","private_key_pem",Base64.getEncoder().encodeToString(pair.getPrivate().getEncoded()),"platform_public_key_pem",Base64.getEncoder().encodeToString(pair.getPublic().getEncoded())),1);}
 AlipayExplicitModeProtocol protocol(){return new AlipayExplicitModeProtocol(http,json);}
 String signed(String key,String body){try{var signer=Signature.getInstance("SHA256withRSA");signer.initSign(pair.getPrivate());signer.update(body.getBytes(StandardCharsets.UTF_8));return "{\""+key+"\":"+body+",\"sign\":\""+Base64.getEncoder().encodeToString(signer.sign())+"\",\"sign_type\":\"RSA2\"}";}catch(Exception e){throw new AssertionError(e);}}
 String trade(String ref,String amount,String currency){return "{ \"code\":\"10000\",\"out_trade_no\":\""+ref+"\",\"trade_no\":\"T001\",\"trade_status\":\"TRADE_SUCCESS\",\"total_amount\":\""+amount+"\",\"trans_currency\":\""+currency+"\" }";}
 @Test void sandboxSignedSuccessNeverConfirmsRealFunds(){when(http.send(any())).thenReturn(signed("alipay_trade_query_response",trade("O1","12.34","CNY")));var receipt=protocol().trade(context("SANDBOX"),"O1");assertFalse(receipt.realFundsConfirmed());assertEquals("1234",receipt.amountMinor().toString());var request=org.mockito.ArgumentCaptor.forClass(HttpRequest.class);verify(http).send(request.capture());assertEquals("openapi-sandbox.dl.alipaydev.com",request.getValue().uri().getHost());assertThrows(IllegalStateException.class,()->PaymentEnvironmentPolicy.requireLiveAccounting(receipt.mode()));}
 @Test void liveResponseUsesLiveHostAndExactSignedWhitespace(){when(http.send(any())).thenReturn(signed("alipay_trade_query_response",trade("O1","12.34","CNY")));assertTrue(protocol().trade(context("LIVE"),"O1").realFundsConfirmed());var request=org.mockito.ArgumentCaptor.forClass(HttpRequest.class);verify(http).send(request.capture());assertEquals("openapi.alipay.com",request.getValue().uri().getHost());}
 @Test void changedSignedAmountIsRejected(){String response=signed("alipay_trade_query_response",trade("O1","12.34","CNY")).replace("12.34","99.99");when(http.send(any())).thenReturn(response);assertThrows(IllegalStateException.class,()->protocol().trade(context("LIVE"),"O1"));}
 @Test void duplicateJsonKeysAreRejectedEvenWithValidSignature(){when(http.send(any())).thenReturn(signed("alipay_trade_query_response",trade("O1","12.34","CNY").replace("\"code\":\"10000\"","\"code\":\"10000\",\"code\":\"10000\"")));assertThrows(IllegalStateException.class,()->protocol().trade(context("LIVE"),"O1"));}
 @Test void receiptMustMatchOriginalReferenceAndCurrencyAndMinorPrecision(){for(String body:List.of(trade("OTHER","12.34","CNY"),trade("O1","12.34","USD"),trade("O1","12.345","CNY"),trade("O1","-1","CNY"))){when(http.send(any())).thenReturn(signed("alipay_trade_query_response",body));assertThrows(IllegalStateException.class,()->protocol().trade(context("LIVE"),"O1"));}}
 @Test void refundRequiresExplicitSuccessAndOriginalRequest(){String body="{\"code\":\"10000\",\"out_trade_no\":\"O1\",\"trade_no\":\"T001\",\"out_request_no\":\"R1\",\"refund_amount\":\"12.34\",\"refund_status\":\"REFUND_SUCCESS\"}";when(http.send(any())).thenReturn(signed("alipay_trade_fastpay_refund_query_response",body));assertFalse(protocol().refund(context("SANDBOX"),"O1","R1").realFundsConfirmed());assertTrue(protocol().refund(context("LIVE"),"O1","R1").realFundsConfirmed());when(http.send(any())).thenReturn(signed("alipay_trade_fastpay_refund_query_response",body.replace("REFUND_SUCCESS","PROCESSING")));assertThrows(IllegalStateException.class,()->protocol().refund(context("LIVE"),"O1","R1"));when(http.send(any())).thenReturn(signed("alipay_trade_fastpay_refund_query_response",body.replace("\"R1\"","\"R2\"")));assertThrows(IllegalStateException.class,()->protocol().refund(context("LIVE"),"O1","R1"));}
 @Test void invalidProviderAndReferenceFailBeforeNetwork(){assertThrows(IllegalArgumentException.class,()->protocol().trade(context("LIVE"),"unsafe&ref"));var wrong=new SocialServiceContext("WXPAY","weixin","LIVE",context("LIVE").values(),1);assertThrows(IllegalArgumentException.class,()->protocol().trade(wrong,"O1"));verifyNoInteractions(http);}
 @Test void paymentEnvironmentPolicyHasNoSandboxFallback(){assertThrows(IllegalArgumentException.class,()->PaymentEnvironmentPolicy.alipayGateway("live"));assertThrows(IllegalStateException.class,()->PaymentEnvironmentPolicy.requireWechatPayLive("SANDBOX"));assertThrows(IllegalStateException.class,()->PaymentEnvironmentPolicy.requireLiveAccounting("SANDBOX"));assertEquals("LIVE",PaymentEnvironmentPolicy.originalPaymentMode(Map.of()));assertEquals("SANDBOX",PaymentEnvironmentPolicy.originalPaymentMode(Map.of("_api_mode","SANDBOX")));assertThrows(IllegalArgumentException.class,()->PaymentEnvironmentPolicy.originalPaymentMode(Map.of("_api_mode","invalid")));}
}
